/**
 * The faces `src/design/tokens.ts` names as each stack's primary family,
 * subset and compressed to WOFF2, and committed as a plain data module rather
 * than a build step, because a face never changes on its own the way
 * `DESIGN.md`'s tokens do. Embedding a face makes it always resolve, which
 * leaves a stack's fallbacks reachable only for a glyph the subset lacks.
 *
 * Geist is the variable face the visual-direction decision names for every
 * proportional role, embedded as one face declaring `font-weight: 100 900`
 * rather than a static per weight. It is Vercel's Geist 1.800, SIL Open Font
 * License 1.1, copyright 2024 The Geist Project Authors, sourced from
 * https://github.com/vercel/geist-font, whose LICENSE.txt is the licence text
 * and whose attribution this comment carries. The committed subset was
 * produced by an earlier session and is kept as found, since it is the exact
 * face the decision was judged against. It covers 226 codepoints, Latin and
 * basic punctuation, and lacks the box-drawing, arrow, check and diamond
 * glyphs the terminal surfaces print, which the mono face carries.
 */

export interface FontFace {
  readonly family: string
  /** The `@font-face` descriptor verbatim: `'400'`, or a range such as `'100 900'`. */
  readonly weight: string
  readonly base64: string
}

const GEIST_VARIABLE =
  ''

/**
 * Geist Mono, the code face beside Geist. Vercel's Geist Mono 1.3.1 from the
 * `geist` npm package, SIL Open Font License 1.1, copyright 2024 The Geist
 * Project Authors, as one variable face subset by `subset-font` to Latin, Latin-1,
 * box drawing, and the arrows, checks, and diamonds the terminal surfaces print.
 */
const GEIST_MONO_VARIABLE =
  ''

/** The proportional face first, then the mono face. */
export const FONT_FACES: readonly FontFace[] = [
  { family: 'Geist Variable', weight: '100 900', base64: GEIST_VARIABLE },
  {
    family: 'Geist Mono Variable',
    weight: '100 900',
    base64: GEIST_MONO_VARIABLE,
  },
]

/**
 * The hand-drawn face pair the figure component draws from: Virgil, Excalidraw's original hand face, and
 * Excalifont, its more legible successor shipped alongside it rather than in
 * place of it (`.canon/groundwork/86-portable-hand-drawn-figures/06-decision.md`
 * item 6). Both are SIL Open Font License, sourced from the excalidraw/excalidraw
 * repository and subset to Latin and basic punctuation.
 */
const VIRGIL_400 =
  ''

const EXCALIFONT_400 =
  ''

export const HAND_DRAWN_FONT_FACES: readonly FontFace[] = [
  { family: 'Virgil', weight: '400', base64: VIRGIL_400 },
  { family: 'Excalifont', weight: '400', base64: EXCALIFONT_400 },
]
